// TestPackGateLog pins the job-start gate line (pack-manifest-audio D7,
// decision_log_test's capture pattern): exactly ONE "pack: gate" INFO line
// per pack job carrying item/class/gate/codecs, the class being the codecs'
// nature with the knob out of the way (opt_in stays visible while the knob is
// off — the gate field owns the knob's verdict), the compact codec-facts
// rendering over the real Matroska shape (hevc Main 10 + two aac LC), and
// INV4 — no path (the ffprobe blob's own filename fact is poisoned with one)
// and no token value ever reach the captured line.
func TestPackGateLog(t *testing.T) {
	// mkvFacts is the REAL Matroska shape from the live diagnosis (finding B):
	// hevc Main 10 level 120, two aac LC streams — plus a poisoned filename
	// fact (ffprobe's format blob carries one) that must never leak (INV4).
	mkvFacts := func() map[string]any {
		return map[string]any{
			"format": map[string]any{"format_name": "matroska,webm", "filename": "/media/library/secret item/file.mkv"},
			"streams": []any{
				map[string]any{"codec_type": "video", "codec_name": "hevc", "profile": "Main 10", "level": 120},
				map[string]any{"codec_type": "audio", "codec_name": "aac", "profile": "LC"},
				map[string]any{"codec_type": "audio", "codec_name": "aac", "profile": "LC"},
			},
		}
	}
	h264Facts := func(format string) map[string]any {
		return map[string]any{
			"format": map[string]any{"format_name": format, "filename": "/media/library/secret item/file." + format},
			"streams": []any{
				map[string]any{"codec_type": "video", "codec_name": "h264", "profile": "High"},
				map[string]any{"codec_type": "audio", "codec_name": "aac"},
			},
		}
	}

	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	for _, tc := range []struct {
		id        string
		ff        map[string]any // the stored facts the closure holds
		knob      bool           // the opt-in knob the closure holds
		wantClass string
		wantGate  string
		wantDodec string
	}{
		// Matroska HEVC, knob off: class stays opt_in (the knob is the gate
		// field's business) and the refusal token rides gate.
		{"hevc_knob_off", mkvFacts(), false, "opt_in", "codec_not_opted_in", "hevc Main 10, aac LC ×2"},
		// Same facts, knob on: open, same codec facts.
		{"hevc_knob_on", mkvFacts(), true, "opt_in", "open", "hevc Main 10, aac LC ×2"},
		// The canonical pack class: h264/aac in a hostile container.
		{"pack_class", h264Facts("matroska,webm"), false, "pack", "open", "h264 High, aac"},
		// A native MP4 pair: direct — the pack lane never needs it, so the
		// gate closes codec_unsupported (PackGate's direct-class verdict).
		{"direct_class", h264Facts("mp4"), false, "direct", "codec_unsupported", "h264 High, aac"},
		// Absent facts fail safe (INV2): direct_only, unsupported, no codecs.
		{"absent_facts", nil, false, "direct_only", "codec_unsupported", "none"},
		// An empty streams array reads the same compact marker.
		{"empty_streams", map[string]any{"streams": []any{}}, false, "direct_only", "codec_unsupported", "none"},
	} {
		t.Run(tc.id, func(t *testing.T) {
			buf.Reset()
			logPackGate("itm_"+tc.id, tc.ff, stream.PackGate(tc.ff, tc.knob))

			var lines []string
			for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
				if strings.Contains(ln, `msg="pack: gate"`) && strings.Contains(ln, "item=itm_"+tc.id) {
					lines = append(lines, ln)
				}
			}
			if len(lines) != 1 {
				t.Fatalf("captured %d pack: gate lines for %s, want 1; output:\n%s", len(lines), tc.id, buf.String())
			}
			for key, want := range map[string]string{
				"class": tc.wantClass, "gate": tc.wantGate, "codecs": tc.wantDodec,
			} {
				// The text handler quotes any value carrying a space.
				field := key + "=" + want
				if strings.Contains(want, " ") {
					field = key + `="` + want + `"`
				}
				if !strings.Contains(lines[0], field) {
					t.Fatalf("gate line %q lacks %q", lines[0], field)
				}
			}

			// INV4: no path — the poisoned filename fact above — and no
			// attribute outside the pinned vocabulary may reach the log.
			if strings.Contains(buf.String(), "/media/library") {
				t.Fatalf("captured log carries a path (INV4): output:\n%s", buf.String())
			}
		})
	}
}

// TestPackGateCodecsRendering pins the pure rendering helper's edge rules
// beside the line pin (pack-manifest-audio D7): multiplicity counting,
// profile-less codecs, unreadable stream entries skipped, and the compact
// empty marker.
func TestPackGateCodecsRendering(t *testing.T) {
	for _, tc := range []struct {
		name string
		ff   map[string]any
		want string
	}{
		{"single_audio_no_multiplicity", map[string]any{"streams": []any{
			map[string]any{"codec_type": "video", "codec_name": "h264"},
			map[string]any{"codec_type": "audio", "codec_name": "aac"},
		}}, "h264, aac"},
		{"three_distinct_audio_tracks", map[string]any{"streams": []any{
			map[string]any{"codec_type": "video", "codec_name": "hevc", "profile": "Main"},
			map[string]any{"codec_type": "audio", "codec_name": "aac", "profile": "LC"},
			map[string]any{"codec_type": "audio", "codec_name": "ac3", "profile": ""},
			map[string]any{"codec_type": "audio", "codec_name": "aac", "profile": "LC"},
		}}, "hevc Main, aac LC ×2, ac3"},
		{"non_map_stream_entries_skipped", map[string]any{"streams": []any{
			"garbage",
			map[string]any{"codec_type": "video", "codec_name": "vp9"},
		}}, "vp9"},
		{"untyped_streams_skipped", map[string]any{"streams": []any{
			map[string]any{"codec_name": "h264"},
		}}, "none"},
		{"missing_streams_key", map[string]any{}, "none"},
		{"non_array_streams", map[string]any{"streams": "nope"}, "none"},
		{"empty_map", map[string]any{}, "none"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := packGateCodecs(tc.ff); got != tc.want {
				t.Errorf("packGateCodecs(%s) = %q, want %q", tc.name, got, tc.want)
			}
		})
	}
}
